import 'package:material_ui/material_ui.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../auth/presentation/auth_controller.dart';import '../data/notification_repository.dart';final notificationRepositoryProvider=Provider((ref)=>NotificationRepository(ref.watch(apiClientProvider)));final notificationsProvider=FutureProvider.autoDispose((ref)=>ref.watch(notificationRepositoryProvider).get());class NotificationsPage extends ConsumerWidget{const NotificationsPage({super.key});@override Widget build(BuildContext context,WidgetRef ref){final n=ref.watch(notificationsProvider);return Scaffold(appBar:AppBar(title:const Text('الإشعارات'),actions:[TextButton(onPressed:()async{await ref.read(notificationRepositoryProvider).readAll();ref.invalidate(notificationsProvider);},child:const Text('قراءة الكل'))]),body:n.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(_,_)=>Center(child:FilledButton(onPressed:()=>ref.invalidate(notificationsProvider),child:const Text('إعادة المحاولة'))),data:(items)=>items.isEmpty?const Center(child:Text('لا توجد إشعارات.')):ListView.separated(itemCount:items.length,separatorBuilder:(_,_)=>const Divider(),itemBuilder:(_,i)=>ListTile(title:Text(items[i].title),subtitle:Text(items[i].body),trailing:items[i].isRead?null:const Icon(Icons.mark_email_unread),onTap:()async{if(!items[i].isRead){await ref.read(notificationRepositoryProvider).read(items[i].id);ref.invalidate(notificationsProvider);}}))));}}